        }
    }

    // Number of alternatives controls how aggressively dead space is avoided.
    let alternatives = fitting_bins_count as f64;
    if fitting_bins_count == 0 {
        score += 5.0;
    } else if fitting_bins_count == 1 {
        score += 5.0 * (1.0 - progress) * waste_ratio.powi(2);
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 1.5 * alternatives.ln().min(3.0) * waste_ratio.powi(2);
        score -= 3.0 * alternatives.ln().min(3.0) * residual_ratio.powi(2);
    }

    // A new bin must beat good existing bins; it is favored mainly for
    // large items, when no small useful gap remains.
    if bin_residual == bin_capacity {
        score += 24.0;
        score -= 13.0 * progress;
        if open_bins_count == 0 {
            score -= 60.0;
        }
        if fitting_bins_count == 0 {
            score -= 24.0;
        }
        score -= 14.0 * size_ratio.max(0.0);
        score += 10.0 * mean_ratio;
    }

    // Mild drift discourages repeatedly leaving low-value fragments.
    score += 0.025 * (step_index as f64).sqrt();
    score -= 0.008 * (total_items as f64).sqrt() * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let size = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let mean = mean_residual.max(0.0);
    let next = next_item_size as f64;
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let pre_ratio = (residual / capacity).clamp(0.0, 1.0);
    let post_ratio = (post / capacity).clamp(0.0, 1.0);
    let mean_ratio = (mean / capacity).clamp(0.0, 1.0);
    let item_ratio = (size / capacity).clamp(0.0, 1.0);
    let fit_count = fitting_bins_count as f64;
    let is_empty = bin_residual == bin_capacity;
    let endgame = progress * progress;

    // Reward compact placements and, in finer granularity, prefer remainders
    // that can plausibly host either the next item or a similarly sized item.
    let mut score = 26.0 * post_ratio.powi(2);
    score -= 13.0 * (1.0 - item_ratio).powi(2);

    if next > 0.0 {
        let next_ratio = (next / capacity).clamp(0.0, 1.0);
        let gap_ratio = (post - next) / capacity;
        let normalized_gap = (gap_ratio / 0.16).clamp(-1.0, 1.0);

        // A zero/small gap is ideal; a remainder materially larger than the
        // next item is less useful and should not be mistaken for a tight fit.
        if gap_ratio >= 0.0 {
            let proximity = 1.0 - normalized_gap;
            score -= 16.0 * proximity * proximity;
            score += 7.0 * gap_ratio.max(0.0).powi(2);
            score -= 5.0 * progress * gap_ratio.max(0.0);
        } else {
            let dead = (-gap_ratio).clamp(0.0, 1.0);
            score += 13.0 * dead * dead;
            score += 2.0 * dead * (1.0 - progress);
        }
    }

    // Consume unusually large holes while avoiding bins that are already
    // substantially tighter than the fleet average.
    let relative = (residual - mean) / capacity;
    score -= 11.0 * relative;
    score += 3.0 * (post_ratio - mean_ratio).abs();
    score += 4.0 * (mean_ratio - pre_ratio).max(0.0);
    score -= 3.0 * (post_ratio - mean_ratio).max(0.0) * (1.0 - progress);

    // Many alternatives reduce the value of any one placement. With one
    // alternative, postpone opening a new bin unless the placement is poor.
    let scarcity = (open_bins_count as f64).sqrt().max(1.0);
    score += 3.0 * (1.0 - progress) / scarcity;
    if fit_count > 1.0 {
        score += 2.4 * (fit_count - 1.0).min(12.0);
    } else {
        score -= 12.0 * (1.0 - progress);
        score += 10.0 * post_ratio;
    }

    // The empty bin is compared on the same residual geometry as open bins.
    // Its advantage is future flexibility, not merely the current placement.
    if is_empty {
        score += 24.0;
        score -= 13.0 * progress;
        score -= 4.0 * item_ratio * (1.0 - progress);

        if open_bins_count == 0 {
            score -= 72.0;
        } else if fit_count == 0 {
            score -= 27.0;
        }

        let fleet_slack = (mean_ratio - post_ratio).max(0.0);
        score += 12.0 * fleet_slack;
        score -= 7.0 * progress * post_ratio;

        if next > 0.0 {
            let next_ratio = (next / capacity).clamp(0.0, 1.0);
            let lookahead_gap = (post_ratio - next_ratio).max(0.0);
            score -= 7.0 * (next_ratio - mean_ratio).max(0.0);
            score += 3.0 * lookahead_gap;
        }

        // Opening is harder to justify when an existing fit leaves a small,
        // actionable remainder. Large dead remainder in the new bin is also
        // costly because it becomes another fragmented hole.
        if fit_count > 0.0 {
            if post_ratio < 0.08 {
                score -= 11.0;
            } else if post_ratio > 0.18 {
                score += 6.0 * (post_ratio - 0.18);
            }
        }
    }

    // Endgame: exact closure is valuable, while preserving a next-item slot
    // remains useful for the final few placements.
    score -= 6.0 * endgame * post_ratio;
    if next > 0.0 {
        let next_ratio = (next / capacity).clamp(0.0, 1.0);
        let useful_slot = (post_ratio - next_ratio).max(0.0);
        score -= 3.0 * endgame * useful_slot;
    }

    score += 0.028 * (step_index as f64).sqrt();
    score -= 0.012 * (total_items as f64).sqrt() * progress;

    score
}
